--- look up an op entry by name.
function M.op(name)
  for _, o in ipairs(M.ops) do if o[1] == name then return o end end
end

--- look up a mod entry by name.
function M.mod(name)
  for _, m in ipairs(M.mods) do if m[1] == name then return m end end
end

return M
